# Builds the test selector (test_selector/, Rust) to Wasm with the Rust
# toolchain in the Chromium tree, and regenerates test_selector_wasm.h, which
# embeds the module's bytes.
#
# Chromium's Rust toolchain has no prebuilt `core` for wasm32, so it is built
# from the toolchain's sources (-Zbuild-std). That needs a few crates from
# crates.io in the Cargo cache; fetch them once, with network access:
#
#   cd third_party/rust-toolchain/lib/rustlib/src/rust/library
#   PATH=$PWD/../../../../../bin:$PATH RUSTC_BOOTSTRAP=1 \
#       cargo fetch --target wasm32-unknown-unknown

set -euo pipefail

cd "$(dirname "$0")"
SRC_ROOT="$(git rev-parse --show-toplevel)"
RUST_BIN="${SRC_ROOT}/third_party/rust-toolchain/bin"
LLVM_BIN="${SRC_ROOT}/third_party/llvm-build/Release+Asserts/bin"
TARGET_DIR="$(mktemp -d)"
trap 'rm -rf "${TARGET_DIR}"' EXIT

(
  cd test_selector
  PATH="${RUST_BIN}:${PATH}" \
  RUSTC_BOOTSTRAP=1 \
  CARGO_TARGET_DIR="${TARGET_DIR}" \
  CARGO_TARGET_WASM32_UNKNOWN_UNKNOWN_LINKER="${LLVM_BIN}/wasm-ld" \
  RUSTFLAGS="-C linker-flavor=wasm-ld" \
  cargo build --release --offline --target wasm32-unknown-unknown \
      -Zbuild-std=core -Zbuild-std-features=panic_immediate_abort
)
WASM="${TARGET_DIR}/wasm32-unknown-unknown/release/test_selector.wasm"

WASM="${WASM}" python3 - <<'EOF'
import os
data = open(os.environ["WASM"], "rb").read()
lines = []
for i in range(0, len(data), 12):
  lines.append("    " + " ".join("0x%02x," % b for b in data[i:i + 12]))
body = "\n".join(lines)
header = f"""// Copyright 2026 The Cobalt Authors. All Rights Reserved.
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
//     http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

// GENERATED by regenerate_test_selector.sh from test_selector/ (Rust).
// DO NOT EDIT.

#ifndef COBALT_SHELL_BROWSER_SPLASH_TESTDATA_TEST_SELECTOR_WASM_H_
#define COBALT_SHELL_BROWSER_SPLASH_TESTDATA_TEST_SELECTOR_WASM_H_

#include <cstdint>

namespace content {{

// {len(data)} bytes.
inline constexpr uint8_t kTestSelectorWasm[] = {{
{body}
}};

}}  // namespace content

#endif  // COBALT_SHELL_BROWSER_SPLASH_TESTDATA_TEST_SELECTOR_WASM_H_
"""
open("test_selector_wasm.h", "w").write(header)
print(f"test_selector.wasm: {len(data)} bytes")
EOF
